//! Shared DTOs between the Rust core and the React UI.
//!
//! These types are the IPC contract. They are format-neutral (eng R7): no
//! jsonc-parser type may appear here. TypeScript mirrors are generated by
//! ts-rs into `src/lib/types/generated/` when `cargo test` runs.

use serde::{Deserialize, Serialize};
use ts_rs::TS;

/// SHA-256 of the exact file bytes, lowercase hex.
pub type Fingerprint = String;

/// RFC 6901 JSON Pointer, e.g. `""` (root), `/logging/level`, `/a~1b`.
pub type Pointer = String;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum DocKind {
    Json,
    Jsonc,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum NodeKind {
    Object,
    Array,
    String,
    Number,
    Boolean,
    Null,
}

/// One node of the document tree as the UI sees it (eng R3, R13).
///
/// Scalars carry their text so numbers keep their exact lexeme (`1.50`,
/// `1e3`, `9007199254740993`). Containers carry `child_count`; `children` is
/// present only up to the requested depth (lazy loading, `get_subtree`).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct TreeNode {
    pub pointer: Pointer,
    /// Object member name; `None` for array items and the root.
    pub key: Option<String>,
    /// Array index; `None` for object members and the root.
    pub index: Option<u32>,
    pub kind: NodeKind,
    /// Scalar text: decoded string for strings, exact lexeme for numbers,
    /// `true`/`false`/`null` for literals. `None` for containers.
    pub text: Option<String>,
    /// Number of children for containers; `None` for scalars.
    pub child_count: Option<u32>,
    /// Loaded children, in document order; `None` when not loaded.
    pub children: Option<Vec<TreeNode>>,
    /// True when this node or a descendant differs from the original file.
    pub changed: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum Severity {
    Error,
    Warning,
    Info,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum DiagnosticSource {
    Syntax,
    DuplicateKey,
    Type,
    /// Built-in preset schema: warnings only (eng R2).
    PresetSchema,
    /// User-associated schema: errors that block Save (A10).
    UserSchema,
    File,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Diagnostic {
    pub severity: Severity,
    pub source: DiagnosticSource,
    /// Stable machine code, e.g. `INVALID_JSON`, `DUPLICATE_KEYS`.
    pub code: String,
    /// Plain-language message without secret values.
    pub message: String,
    pub pointer: Option<Pointer>,
    /// 1-based.
    pub line: Option<u32>,
    /// 1-based.
    pub column: Option<u32>,
}

/// A draft edit. Values are strict JSON text (`"\"abc\""`, `1.50`, `true`,
/// `{}`) so the UI never round-trips numbers through JS floats (eng R3).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "op", rename_all = "kebab-case")]
#[ts(export)]
pub enum DraftOp {
    /// Replace the value of an existing member/item. Error if absent.
    Set {
        path: Pointer,
        #[serde(rename = "valueJson")]
        #[ts(rename = "valueJson")]
        value_json: String,
    },
    /// Add a new object member (appended). Error if it already exists.
    Add {
        path: Pointer,
        #[serde(rename = "valueJson")]
        #[ts(rename = "valueJson")]
        value_json: String,
    },
    /// Remove an object member or array item.
    Remove { path: Pointer },
    /// Insert into the array at `path` before `index` (`index == len` appends).
    ArrayInsert {
        path: Pointer,
        index: u32,
        #[serde(rename = "valueJson")]
        #[ts(rename = "valueJson")]
        value_json: String,
    },
    /// Move an item within the array at `path`.
    ArrayMove { path: Pointer, from: u32, to: u32 },
    /// Rename an object member in place (correction C1).
    RenameKey {
        path: Pointer,
        #[serde(rename = "newKey")]
        #[ts(rename = "newKey")]
        new_key: String,
    },
}

/// Response to apply/undo/redo/revert/reapply (eng R13): only what changed.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct EditResult {
    /// Monotonic per open document; tags async schema diagnostics (R14).
    #[ts(type = "number")]
    pub revision: u64,
    /// Re-rendered nodes (each with children to depth 1). Replace these in
    /// the UI cache; invalidate their descendants.
    pub changed: Vec<TreeNode>,
    /// Pointers that no longer exist.
    pub removed: Vec<Pointer>,
    /// Pointers of containers whose child list changed (insert/move/remove).
    pub reshaped: Vec<Pointer>,
    pub dirty_count: u32,
    pub can_undo: bool,
    pub can_redo: bool,
    /// Synchronous diagnostics (syntax/duplicate/type) for the whole draft.
    pub diagnostics: Vec<Diagnostic>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum LineEnding {
    Lf,
    Crlf,
    Mixed,
    None,
}

/// A byte range in `SourceView::text` that is masked (eng R17).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct MaskSpan {
    pub id: u32,
    /// UTF-16 code unit offsets into `text` for direct use in JS.
    pub start: u32,
    pub end: u32,
}

/// Read-only source for files that cannot be edited (design DD4).
/// `text` already has masked values replaced by `•` runs of equal length.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SourceView {
    pub text: String,
    pub masks: Vec<MaskSpan>,
    /// Lines to highlight (1-based), e.g. the error line or all duplicates.
    pub highlight_lines: Vec<u32>,
    /// Caret position for the primary error (1-based).
    pub caret: Option<SourceCaret>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SourceCaret {
    pub line: u32,
    pub column: u32,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DocumentSnapshot {
    pub file_id: String,
    pub kind: DocKind,
    pub fingerprint: Fingerprint,
    #[ts(type = "number")]
    pub size_bytes: u64,
    pub has_bom: bool,
    pub line_ending: LineEnding,
    /// False for invalid syntax, duplicate keys, or other blocking states.
    pub editable: bool,
    pub read_only: bool,
    /// Root with children to depth 1; `None` when not editable.
    pub root: Option<TreeNode>,
    /// Present when not editable because of a syntax/duplicate error.
    pub source_view: Option<SourceView>,
    pub diagnostics: Vec<Diagnostic>,
    #[ts(type = "number")]
    pub revision: u64,
    pub dirty_count: u32,
    pub can_undo: bool,
    pub can_redo: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum ChangeKind {
    Added,
    Removed,
    Changed,
    Moved,
    Renamed,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct SemanticChange {
    pub pointer: Pointer,
    pub kind: ChangeKind,
    /// Display text of the old/new value; masked as `••••` when secret-like.
    pub old_text: Option<String>,
    pub new_text: Option<String>,
    pub masked: bool,
    /// Index into the draft op list; `None` for disk-side changes.
    pub op_index: Option<u32>,
    /// False when a later op depends on this one (design DD15, R18).
    pub revertible: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum DiffLineKind {
    Context,
    Added,
    Removed,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DiffLine {
    pub kind: DiffLineKind,
    /// 1-based line numbers in old/new text.
    pub old_line: Option<u32>,
    pub new_line: Option<u32>,
    pub text: String,
    /// Mask ids (see `reveal_masked_value`) with UTF-16 ranges inside `text`.
    pub masks: Vec<MaskSpan>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DiffHunk {
    pub lines: Vec<DiffLine>,
}

/// Review changes dialog payload (design DD15).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ChangeSummary {
    pub changes: Vec<SemanticChange>,
    pub hunks: Vec<DiffHunk>,
    /// Preset-schema warnings: save allowed after confirmation (eng R2).
    pub warnings: Vec<Diagnostic>,
    /// Blocking errors: save disabled.
    pub errors: Vec<Diagnostic>,
}

/// Conflict dialog payload (design DD16, eng R16, C3, C4).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ConflictInfo {
    pub disk_fingerprint: Fingerprint,
    /// Original → disk. Empty when the disk version does not parse.
    pub disk_changes: Vec<SemanticChange>,
    /// Original → draft.
    pub draft_changes: Vec<SemanticChange>,
    /// Draft pointers that overlap a disk change ("both changed").
    pub overlapping: Vec<Pointer>,
    pub can_reapply: bool,
    /// Set when the disk version is not valid JSON/JSONC.
    pub disk_parse_error: Option<Diagnostic>,
}

