#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum EntryKind {
    /// A user file registered by path.
    File,
    /// The sample copy in the app data dir (design DD7, correction C2).
    Sample,
}

/// Registry entry: metadata only, never file contents (spec §8).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ManagedDocument {
    pub id: String,
    pub display_name: String,
    /// Path as registered (may be a symlink).
    pub absolute_path: String,
    pub kind: DocKind,
    pub entry_kind: EntryKind,
    pub preset_id: Option<String>,
    pub local_schema_path: Option<String>,
    pub collection_id: Option<String>,
    pub discovered_scope: Option<Scope>,
    /// Policy read-only (managed settings) — independent of file permissions.
    pub read_only: bool,
    /// One-time confirmation for symlink write-through (eng R5).
    pub link_write_confirmed: bool,
    /// One-time confirmation that saving detaches hard links (eng R5).
    pub hardlink_write_confirmed: bool,
    /// RFC 3339.
    pub last_opened_at: Option<String>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
