/// A Claude Code settings candidate (spec §7, design R1 hint).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DiscoveredCandidate {
    /// Opaque, Rust-issued (eng R6); pass to `add_discovered_file`.
    pub candidate_id: String,
    pub path: String,
    pub scope: Scope,
    pub exists: bool,
    pub read_only: bool,
    pub already_registered: bool,
    pub note: Option<String>,
}

/// Schema-derived hints for one field (spec §5/§6).
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct FieldHint {
    pub pointer: Pointer,
    /// JSON Schema `type` (`"boolean"`, `"integer"`, …), first non-null one.
    pub value_type: Option<String>,
    /// Listed in the parent's `required`.
    pub required: bool,
    pub title: Option<String>,
    pub description: Option<String>,
    /// Allowed values as JSON text.
    pub enum_values: Option<Vec<String>>,
    /// Schema default as JSON text (hint only, never written).
    pub default_json: Option<String>,
    pub format: Option<String>,
    pub minimum: Option<String>,
    pub maximum: Option<String>,
    pub min_length: Option<u32>,
    pub max_length: Option<u32>,
    pub pattern: Option<String>,
    pub secret: bool,
    /// Schema-known optional properties not present in the file (Add setting menu).
    pub addable_properties: Vec<String>,
    /// `additionalProperties` allowed (map editor).
    pub open_map: bool,
    /// Preset `itemSummary` field for arrays of objects (design DD17).
    pub item_summary: Option<String>,
    /// Sensitive setting warning (spec §7, e.g. permissions).
    pub sensitive: bool,
}

